psql -d warehouse -v ON_ERROR_STOP=1 <<'SQL'
BEGIN;
CREATE TEMP TABLE pilot_stage (customer_id integer, name text, email text);
\copy pilot_stage (customer_id, name, email) FROM '/home/sam/data/incoming/pilot_customers.csv' WITH (FORMAT csv, HEADER true)
DO $$ BEGIN
  IF (SELECT count(*) FROM pilot_stage) <> 40 THEN RAISE EXCEPTION 'expected 40 rows'; END IF;
END $$;
INSERT INTO customers (customer_id, name, email, source, is_test)
SELECT customer_id, name, email, 'pilot_import', true FROM pilot_stage;
SELECT count(*) AS inserted FROM customers WHERE source = 'pilot_import';
COMMIT;
